wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(24916402481481267506)
,p_plug_name=>'Status List'
,p_static_id=>'content-row'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'from (',
'    select',
'        level as seq,',
'        case mod(level - 1, 5)',
'            when 0 then ''Task''',
'            when 1 then ''Document''',
'            when 2 then ''Approval''',
'            when 3 then ''Dataset''',
'            else ''Configuration''',
'        end as overline,',
'        ''Dashboard Item '' || level as title,',
'        ''Representative workflow item '' || level as description,',
'        case mod(level - 1, 5)',
'            when 0 then ''fa-clipboard-list''',
'            when 1 then ''fa-file-text-o''',
'            when 2 then ''fa-user-check''',
'            when 3 then ''fa-database''',
'            else ''fa-cogs''',
'        end as icon,',
'        case mod(level - 1, 5)',
'            when 0 then ''Complete''',
'            when 1 then ''In Progress''',
'            when 2 then ''Needs Review''',
'            when 3 then ''Available''',
'            else ''Updated''',
'        end as badge,',
'        case mod(level - 1, 5)',
'            when 0 then ''success''',
'            when 1 then ''warning''',
'            when 2 then ''danger''',
'            when 3 then ''info''',
'            else ''success''',
'        end as badge_state,',
'        null as badge_icon',
'    from dual',
'    connect by level <= 7',
')'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>15
